mapper.select:
select id, user_id, receiver_name, receiver_phone, province, city, district, detail_address, is_default, create_time, update_time
from user_address
where id = #{id}

select id, user_id, goods_id, create_time from user_favorite
where user_id = #{userId} and goods_id = #{goodsId}
limit 1

select id, user_id, goods_id, browse_time from user_browse_history
where user_id = #{userId}
order by browse_time desc
limit #{limit}

mapper.delete:
delete from user_browse_history
where user_id = #{userId}
and id not in (
    select id from (
        select id from user_browse_history
        where user_id = #{userId}
        order by browse_time desc
        limit #{keep}
    ) t
)
